import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath, pathToFileURL } from "node:url";
import path from "node:path";

import openapiTS, { astToString } from "openapi-typescript";

export const SCHEMA_HEADER =
  "/* GENERATED by web/scripts/gen-api-types.mjs from lib/api/openapi.json — do not edit. " +
  "On merge conflict: regenerate with `npm run api:sync`, never hand-merge. */";

/** The openapi-typescript v7 Node API. `defaultNonNullable: false` matches FastAPI's output:
 * output schemas list defaulted fields as required, input schemas leave them optional. */
export async function renderSchema(doc) {
  const ast = await openapiTS(doc, { defaultNonNullable: false, alphabetize: true });
  const body = astToString(ast).replace(/\r\n?/g, "\n");
  return `${SCHEMA_HEADER}\n${body.endsWith("\n") ? body : `${body}\n`}`;
}

async function main() {
  const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
  const source = path.join(root, "lib", "api", "openapi.json");
  const target = path.join(root, "lib", "api", "schema.d.ts");
  const doc = JSON.parse(await readFile(source, "utf8"));
  await writeFile(target, await renderSchema(doc), "utf8");
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  await main();
}
